def overlay(base, patch):
    """Recursively merge dictionaries, replace lists, and copy inputs."""
    if not isinstance(base, dict) or not isinstance(patch, dict):
        raise TypeError("overlay expects two dictionaries")

    def clone(value):
        if isinstance(value, dict):
            return {key: clone(item) for key, item in value.items()}
        if isinstance(value, list):
            return [clone(item) for item in value]
        return value

    result = clone(base)
    for key, patch_value in patch.items():
        if key in result and isinstance(result[key], dict) and isinstance(patch_value, dict):
            result[key] = overlay(result[key], patch_value)
        else:
            result[key] = clone(patch_value)
    return result

import copy
import unittest

from src.merge_config import overlay


class ChangedOverlayTests(unittest.TestCase):
    def test_none_deletes_existing_nested_key(self):
        base = {"service": {"host": "old", "port": 80}, "debug": True}
        patch = {"service": {"port": None}}
        self.assertEqual(
            overlay(base, patch),
            {"service": {"host": "old"}, "debug": True},
        )

    def test_nested_missing_none_is_noop_and_other_key_is_added(self):
        self.assertEqual(
            overlay({}, {"new": {"missing": None, "value": 2}}),
            {"new": {"value": 2}},
        )

    def test_patch_dict_replacing_scalar_processes_deletions(self):
        self.assertEqual(
            overlay({"new": 9}, {"new": {"missing": None, "value": 2}}),
            {"new": {"value": 2}},
        )

    def test_lists_are_replaced_and_none_elements_are_preserved(self):
        self.assertEqual(
            overlay({"items": [1, 2]}, {"items": [None, 3]}),
            {"items": [None, 3]},
        )

    def test_changed_contract_does_not_mutate_inputs(self):
        base = {"service": {"host": "old", "port": 80}, "items": [1]}
        patch = {"service": {"port": None}, "items": [2]}
        base_before = copy.deepcopy(base)
        patch_before = copy.deepcopy(patch)
        result = overlay(base, patch)
        self.assertEqual(result, {"service": {"host": "old"}, "items": [2]})
        self.assertEqual(base, base_before)
        self.assertEqual(patch, patch_before)


if __name__ == "__main__":
    unittest.main()

def overlay(base, patch):
    """Merge dictionaries, delete with None, replace lists, and copy inputs."""
    if not isinstance(base, dict) or not isinstance(patch, dict):
        raise TypeError("overlay expects two dictionaries")

    def clone(value):
        if isinstance(value, dict):
            return {key: clone(item) for key, item in value.items()}
        if isinstance(value, list):
            return [clone(item) for item in value]
        return value

    result = clone(base)
    for key, patch_value in patch.items():
        if patch_value is None:
            result.pop(key, None)
        elif isinstance(patch_value, dict):
            existing = result.get(key)
            if not isinstance(existing, dict):
                existing = {}
            result[key] = overlay(existing, patch_value)
        else:
            result[key] = clone(patch_value)
    return result
